# Takes as input an unordered embedding dataset along with metadata generated by 
# clip-retrieval and reorders the embeddings to match the order of the image dataset.

mkdir /home/datasets/laion_aesthetics_65p_embeds_v3/img_emb_ordered
mkdir /home/datasets/laion_aesthetics_65p_embeds_v3/text_emb_ordered

reorder-embeddings reorder \
	--embeddings-folder=/home/datasets/laion_aesthetics_65p_embeds_v3/img_emb \
	--metadata-folder=/home/datasets/laion_aesthetics_65p_embeds_v3/metadata \
	--output-folder=/home/datasets/laion_aesthetics_65p_embeds_v3/img_emb_ordered \
	--index-width=4 \
	--output-shard-width=5 \
	--limit=62 \
	--run-concurrent=1 \
	--verbose=true

reorder-embeddings reorder \
	--embeddings-folder=/home/datasets/laion_aesthetics_65p_embeds_v3/text_emb \
	--metadata-folder=/home/datasets/laion_aesthetics_65p_embeds_v3/metadata \
	--output-folder=/home/datasets/laion_aesthetics_65p_embeds_v3/text_emb_ordered \
	--index-width=4 \
	--output-shard-width=5 \
	--limit=62 \
	--run-concurrent=1 \
	--verbose=true

